def _maybe_fetch_remote_processed(fname: str) -> Optional[Path]:
    """Optionally fetch a processed artifact from GitHub raw if missing locally.

    Controlled by env var ALLOW_REMOTE_ARTIFACTS in {"1","true","yes"}.
    Saves to data/processed/<fname> on success and returns that Path.
    """
    try:
        allow = str(os.environ.get("ALLOW_REMOTE_ARTIFACTS", "0")).strip().lower() in {"1", "true", "yes"}
        if not allow:
            return None
        # Only allow safe filenames under processed/
        if not fname or "/" in fname or ".." in fname:
            return None
        out = DATA_PROCESSED_DIR / fname
        if out.exists():
            return out
        repo = os.environ.get("GITHUB_REPOSITORY") or "mostgood1/WNBA-Betting"
        branch = os.environ.get("GIT_BRANCH") or os.environ.get("RENDER_GIT_BRANCH") or "main"
        url = f"https://raw.githubusercontent.com/{repo}/{branch}/data/processed/{fname}"
        try:
            import requests as _rq  # type: ignore
        except Exception:
            return None
        try:
            r = _rq.get(url, timeout=8, headers={
                "User-Agent": "wnba-betting/props-backend",
                "Accept": "text/csv,application/octet-stream,*/*",
            })
            if r.status_code != 200 or not r.content:
                return None
            out.parent.mkdir(parents=True, exist_ok=True)
            with out.open("wb") as f:
                f.write(r.content)
            return out
        except Exception:
            return None
    except Exception:
        return None


def _active_predictions_league_tricodes() -> set[str]:
    league_code = str(getattr(LEAGUE, "code", "") or "").strip().lower()
    if league_code == "wnba":
        return {str(tri).strip().upper() for tri in _WNBA_OFFICIAL_LOGO_TEAM_IDS}
    return set()


def _predictions_file_matches_active_league(path: Path) -> bool:
    expected_tris = _active_predictions_league_tricodes()
    if not expected_tris:
        return True

    df = _read_csv_if_exists(path)
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return False

    observed_tris: set[str] = set()
    for home_col, away_col in (("home_team", "visitor_team"), ("home_team", "away_team"), ("home", "away")):
        if home_col not in df.columns or away_col not in df.columns:
            continue
        for _, row in df.head(12).iterrows():
            for value in (row.get(home_col), row.get(away_col)):
                tri = _canonical_team_tri(value)
                if tri:
                    observed_tris.add(tri)
        if observed_tris:
            break

    if not observed_tris:
        return False
    return observed_tris.issubset(expected_tris)


def _json_primitive(x):
    """Convert numpy/pandas scalars and datetimes to native JSON-serializable types.

    Strict mode: coerce NaN/Inf to None so JSON is valid (browsers reject NaN/Infinity).
    """
    try:
        # Normalize pandas/NumPy NA first (including plain float('nan'))
        try:
            if x is None:
                return None
            # pandas/NumPy NA detection
            try:
                if pd.isna(x):
                    return None
            except Exception:
                pass
            # Explicitly guard floats for NaN/Inf
            if isinstance(x, float):
                if not np.isfinite(x):
                    return None
                return float(x)
            # NumPy numeric scalars
            if isinstance(x, np.floating):
                xv = float(x)
                if not np.isfinite(xv):
                    return None
                return xv
            if isinstance(x, np.integer):
                return int(x)
        except Exception:
            pass

        # Primitive JSON-safe types
        if isinstance(x, (str, bool, int)):
            return x
        # numpy scalar -> python scalar
        if isinstance(x, np.generic):
            try:
                return x.item()
            except Exception:
                pass
        # datetime-like -> ISO string
        if isinstance(x, (datetime,)):
            try:
                return x.isoformat()
            except Exception:
                return str(x)
        # pandas timestamp
        try:
            import pandas as _pd  # local alias
            if isinstance(x, _pd.Timestamp):
                return x.to_pydatetime().isoformat()
        except Exception:
            pass
        # numpy datetime64
        try:
            if isinstance(x, (np.datetime64,)):
                return str(x)
        except Exception:
            pass
        return x
    except Exception:
        return x


def _to_jsonable(obj):
    """Recursively convert container of dict/list/tuple/numpy/pandas scalars to JSONable primitives."""
    try:
        if isinstance(obj, dict):
            return {str(k): _to_jsonable(v) for k, v in obj.items()}
        if isinstance(obj, (list, tuple, set)):
            return [ _to_jsonable(v) for v in obj ]
        # numpy arrays -> lists
        try:
            if isinstance(obj, np.ndarray):
                return [ _to_jsonable(v) for v in obj.tolist() ]
        except Exception:
            pass
        return _json_primitive(obj)
    except Exception:
        return obj


def _find_predictions_for_date(date_str: str) -> Optional[Path]:
    fname = f"predictions_{date_str}.csv"
    for p in _processed_path_candidates(fname, prefer_repo=True):
        if not p.exists() and p.parent == DATA_PROCESSED_DIR:
            try:
                _maybe_fetch_remote_processed(p.name)
            except Exception:
                pass
        if p.exists() and _predictions_file_matches_active_league(p):
            return p
    # Legacy root fallback
    legacy = BASE_DIR / f"predictions_{date_str}.csv"
    if legacy.exists() and _predictions_file_matches_active_league(legacy):
        return legacy
    return None


def _find_game_odds_for_date(date_str: str) -> Optional[Path]:
    fname = f"game_odds_{date_str}.csv"
    for p in _processed_path_candidates(fname, prefer_repo=True):
        if not p.exists() and p.parent == DATA_PROCESSED_DIR:
            try:
                _maybe_fetch_remote_processed(p.name)
            except Exception:
                pass
        if p.exists():
            return p
    # Alternate names we search for
    for name in [
        f"closing_lines_{date_str}.csv",
        f"odds_{date_str}.csv",
        f"market_{date_str}.csv",
    ]:
        for q in _processed_path_candidates(name, prefer_repo=True):
            if not q.exists() and q.parent == DATA_PROCESSED_DIR:
                try:
                    _maybe_fetch_remote_processed(q.name)
                except Exception:
                    pass
            if q.exists():
                return q
    return None


def _american_to_implied_prob(amer: Any) -> float | None:
    try:
        a = float(amer)
    except Exception:
        return None
    if not np.isfinite(a) or a == 0:
        return None
    if a > 0:
        return float(100.0 / (a + 100.0))
    return float(abs(a) / (abs(a) + 100.0))


def _safe_float(x: Any) -> float | None:
    try:
        v = float(x)
        return float(v) if np.isfinite(v) else None
    except Exception:
        return None


def _processed_path_candidates(fname: str, *, prefer_repo: bool = False) -> list[Path]:
    try:
        raw_name = str(fname or "").strip()
        if not raw_name or "/" in raw_name or "\\" in raw_name or ".." in raw_name:
            return []
        primary = REPO_DATA_PROCESSED_DIR if prefer_repo else DATA_PROCESSED_DIR
        secondary = DATA_PROCESSED_DIR if prefer_repo else REPO_DATA_PROCESSED_DIR
        candidates: list[Path] = []
        seen: set[str] = set()
        for root in (primary, secondary):
            try:
                path = root / raw_name
                key = str(path)
                if key in seen:
                    continue
                seen.add(key)
                candidates.append(path)
            except Exception:
                continue
        return candidates
    except Exception:
        return []


def _load_smart_sim_files_for_date(date_str: str, prefix: str | None = None) -> list[Path]:
    try:
        pref = str(prefix or os.environ.get("SMART_SIM_PREFIX") or "smart_sim").strip() or "smart_sim"
        patterns: list[Path] = []
        seen_names: set[str] = set()
        for root in (REPO_DATA_PROCESSED_DIR, DATA_PROCESSED_DIR):
            try:
                for path in sorted(root.glob(f"{pref}_{date_str}_*.json")):
                    name = str(path.name or "")
                    if not name or name in seen_names:
                        continue
                    seen_names.add(name)
                    patterns.append(path)
            except Exception:
                continue
        return patterns
    except Exception:
        return []


def _smart_sim_matchup_from_path(date_str: str, path: Path, prefix: str | None = None) -> tuple[str, str] | None:
    try:
        pref = str(prefix or os.environ.get("SMART_SIM_PREFIX") or "smart_sim").strip() or "smart_sim"
        stem = str(path.stem or "")
        marker = f"{pref}_{date_str}_"
        if not stem.startswith(marker):
            return None
        tail = stem[len(marker):]
        parts = tail.split("_")
        if len(parts) < 2:
            return None
        home_tri = str(parts[0] or "").strip().upper()
        away_tri = str(parts[1] or "").strip().upper()
        if len(home_tri) != 3 or len(away_tri) != 3:
            return None
        return home_tri, away_tri
    except Exception:
        return None


def _smart_sim_authoritative_matchups_for_date(date_str: str) -> set[tuple[str, str]]:
    out: set[tuple[str, str]] = set()

    def _schedule_matchups() -> set[tuple[str, str]]:
        schedule_out: set[tuple[str, str]] = set()

        def _tri(raw: Any) -> str:
            val = str(raw or "").strip()
            if not val:
                return ""
            tri = _get_tricode(val)
            return str(tri or val).strip().upper()

        try:
            sched_path = _processed_schedule_json_path(date_str)
            schedule_rows = _read_json_if_exists(sched_path)
            if isinstance(schedule_rows, list):
                for game in schedule_rows:
                    if not isinstance(game, dict):
                        continue
                    game_date = str(game.get("date_est") or game.get("date_utc") or "")[:10]
                    if game_date != str(date_str):
                        continue
                    home_tri = _tri(game.get("home_tricode") or game.get("home_team") or game.get("home_name"))
                    away_tri = _tri(game.get("away_tricode") or game.get("away_team") or game.get("away_name"))
                    if home_tri and away_tri:
                        schedule_out.add((home_tri, away_tri))
        except Exception:
            return set()

        return schedule_out

    out = _schedule_matchups()
    if out:
        return out

    try:
        odds_map = _load_game_odds_map(date_str)
        out = {
            (str(home_tri or "").strip().upper(), str(away_tri or "").strip().upper())
            for home_tri, away_tri in odds_map.keys()
            if str(home_tri or "").strip() and str(away_tri or "").strip()
        }
    except Exception:
        out = set()

    if out:
        return out

    pred_path = _find_predictions_for_date(date_str)

    try:
        df = _read_csv_if_exists(pred_path)
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return out

        def _tri(raw: Any) -> str:
            val = str(raw or "").strip()
            if not val:
                return ""
            tri = _get_tricode(val)
            return str(tri or val).strip().upper()

        for home_col, away_col in (("home_team", "visitor_team"), ("home", "away")):
            if home_col not in df.columns or away_col not in df.columns:
                continue
            for _, row in df.iterrows():
                home_tri = _tri(row.get(home_col))
                away_tri = _tri(row.get(away_col))
                if home_tri and away_tri:
                    out.add((home_tri, away_tri))
            if out:
                break
    except Exception:
        return out

    return out


def _load_smart_sim_files_for_authoritative_slate(date_str: str, prefix: str | None = None) -> list[Path]:
    files = _load_smart_sim_files_for_date(date_str, prefix=prefix)
    allowed_matchups = _smart_sim_authoritative_matchups_for_date(date_str)
    if not allowed_matchups:
        return files

    try:
        pref = str(prefix or os.environ.get("SMART_SIM_PREFIX") or "smart_sim").strip() or "smart_sim"
        existing_matchups = {
            matchup
            for matchup in (
                _smart_sim_matchup_from_path(date_str, fp, prefix=prefix)
                for fp in files
            )
            if matchup is not None
        }
        for home_tri, away_tri in sorted(allowed_matchups - existing_matchups):
            _maybe_fetch_remote_processed(f"{pref}_{date_str}_{home_tri}_{away_tri}.json")
        files = _load_smart_sim_files_for_date(date_str, prefix=prefix)
    except Exception:
        pass

    if not files:
        return files

    filtered: list[Path] = []
    for fp in files:
        matchup = _smart_sim_matchup_from_path(date_str, fp, prefix=prefix)
        if matchup is None or matchup in allowed_matchups:
            filtered.append(fp)
    return filtered


def _load_game_odds_map(date_str: str) -> dict[tuple[str, str], dict[str, Any]]:
    out: dict[tuple[str, str], dict[str, Any]] = {}
    try:
        p = _find_game_odds_for_date(date_str)
        if not p:
            return out
        df = pd.read_csv(p)
        if df is None or df.empty:
            return out

        def _tri(x: Any) -> str:
            t = _get_tricode(str(x))
            return (t or str(x or "").strip().upper()).strip().upper()

        for _, r in df.iterrows():
            ht = _tri(r.get("home_team"))
            at = _tri(r.get("visitor_team"))
            if not ht or not at:
                continue
            out[(ht, at)] = r.to_dict()
    except Exception:
        return out
    return out


def _best_bets_clamp01(value: Any) -> float:
    v = _safe_float(value)
    if v is None:
        return 0.0
    return float(max(0.0, min(1.0, v)))


def _best_bets_pick_first_numeric(mapping: Any, *names: str) -> float | None:
    if mapping is None:
        return None
    for name in names:
        try:
            value = mapping.get(name)  # type: ignore[attr-defined]
        except Exception:
            value = None
        number = _safe_float(value)
        if number is not None:
            return float(number)
    return None


@lru_cache(maxsize=16)
def _load_best_bets_props_team_scoring_context(date_str: str) -> dict[str, dict[str, Any]]:
    path = DATA_PROCESSED_DIR / f"props_predictions_{date_str}.csv"
    if not path.exists():
        try:
            _maybe_fetch_remote_processed(path.name)
        except Exception:
            pass
    df = _read_csv_if_exists(path)
    out: dict[str, dict[str, Any]] = {}
    if not isinstance(df, pd.DataFrame) or df is None or df.empty:
        return out

    for _, raw in df.iterrows():
        team_key = (_get_tricode(raw.get("team")) or str(raw.get("team") or "").strip().upper())
        if not team_key:
            continue
        entry = out.setdefault(
            team_key,
            {"points_sum": 0.0, "minutes_sum": 0.0, "players": 0, "players_with_points": 0},
        )
        entry["players"] = int(entry.get("players") or 0) + 1

        pts_mean = _best_bets_pick_first_numeric(raw, "pts_mean", "pred_pts", "points_mean", "pred_points")
        if pts_mean is not None and float(pts_mean) >= 0.0:
            entry["points_sum"] = float(entry.get("points_sum") or 0.0) + float(pts_mean)
            entry["players_with_points"] = int(entry.get("players_with_points") or 0) + 1

        min_mean = _best_bets_pick_first_numeric(raw, "min_mean", "pred_min", "minutes_mean", "pred_minutes")
        if min_mean is not None and float(min_mean) > 0.0:
            entry["minutes_sum"] = float(entry.get("minutes_sum") or 0.0) + float(min_mean)

    for team_key, entry in out.items():
        regulation_team_minutes = max(1.0, float(getattr(LEAGUE, "regulation_team_minutes", 240.0)))
        minutes_sum = max(0.0, min(regulation_team_minutes, float(entry.get("minutes_sum") or 0.0)))
        coverage = _best_bets_clamp01(minutes_sum / regulation_team_minutes) if minutes_sum > 0.0 else 0.0
        points_sum = max(0.0, float(entry.get("points_sum") or 0.0))
        players_with_points = int(entry.get("players_with_points") or 0)

        prop_team_total = None
        if points_sum > 0.0:
            if minutes_sum >= (regulation_team_minutes / 2.0):
                prop_team_total = float(points_sum / max(0.55, coverage))
            else:
                per_min = float(points_sum / max(1.0, minutes_sum)) if minutes_sum > 0.0 else 0.0
                prop_team_total = float(points_sum + (per_min * max(0.0, regulation_team_minutes - minutes_sum) * 0.55))
            prop_team_total = float(max(70.0, min(140.0, prop_team_total)))

        blend_weight = max(0.0, min(0.60, (coverage - 0.45) / 0.55)) if coverage > 0.45 else 0.0
        if players_with_points < 7:
            blend_weight *= 0.6

        entry["minutes_sum"] = minutes_sum
        entry["minutes_coverage"] = round(float(coverage), 4)
        entry["team_total_points"] = prop_team_total
        entry["blend_weight"] = round(float(max(0.0, min(0.60, blend_weight))), 4)
        entry["team"] = team_key

    return out


def _best_bets_adjust_matchup_total(
    *,
    raw_total: float | None,
    raw_margin: float | None,
    market_total: float | None,
    home_prop_ctx: dict[str, Any] | None,
    away_prop_ctx: dict[str, Any] | None,
    home_off: float | None,
    away_off: float | None,
    home_def: float | None,
    away_def: float | None,
    league_off: float | None,
    league_def: float | None,
    home_recent_offense: float | None,
    away_recent_offense: float | None,
    home_recent_allowed: float | None,
    away_recent_allowed: float | None,
    league_recent_offense: float | None,
    league_recent_allowed: float | None,
    game_pace: float | None,
    league_pace: float | None,
) -> dict[str, float | None]:
    home_base = None
    away_base = None
    if raw_total is not None and raw_margin is not None:
        try:
            home_base = 0.5 * (float(raw_total) + float(raw_margin))
            away_base = 0.5 * (float(raw_total) - float(raw_margin))
        except Exception:
            home_base = None
            away_base = None

    home_prop_total = _safe_float((home_prop_ctx or {}).get("team_total_points")) if isinstance(home_prop_ctx, dict) else None
    away_prop_total = _safe_float((away_prop_ctx or {}).get("team_total_points")) if isinstance(away_prop_ctx, dict) else None
    home_prop_weight = _safe_float((home_prop_ctx or {}).get("blend_weight")) if isinstance(home_prop_ctx, dict) else None
    away_prop_weight = _safe_float((away_prop_ctx or {}).get("blend_weight")) if isinstance(away_prop_ctx, dict) else None
    home_prop_weight = 0.0 if home_prop_weight is None else float(max(0.0, min(0.60, home_prop_weight)))
    away_prop_weight = 0.0 if away_prop_weight is None else float(max(0.0, min(0.60, away_prop_weight)))

    home_prop_blend = home_base
    if home_prop_total is not None:
        if home_base is not None:
            home_prop_blend = float((1.0 - home_prop_weight) * float(home_base) + home_prop_weight * float(home_prop_total))
        else:
            home_prop_blend = float(home_prop_total)

    away_prop_blend = away_base
    if away_prop_total is not None:
        if away_base is not None:
            away_prop_blend = float((1.0 - away_prop_weight) * float(away_base) + away_prop_weight * float(away_prop_total))
        else:
            away_prop_blend = float(away_prop_total)

    prop_blended_total = raw_total
    if home_prop_blend is not None and away_prop_blend is not None:
        prop_blended_total = float(home_prop_blend + away_prop_blend)

    prop_blended_margin = None
    if home_prop_blend is not None and away_prop_blend is not None:
        prop_blended_margin = float(home_prop_blend - away_prop_blend)

    matchup_adjustment = 0.0
    pace_gap = None
    if game_pace is not None and league_pace is not None:
        pace_gap = float(game_pace) - float(league_pace)
        matchup_adjustment += 0.28 * float(pace_gap)
    if home_off is not None and away_off is not None and league_off is not None:
        matchup_adjustment += 0.10 * ((float(home_off) - float(league_off)) + (float(away_off) - float(league_off)))
    if home_def is not None and away_def is not None and league_def is not None:
        matchup_adjustment += 0.10 * ((float(home_def) - float(league_def)) + (float(away_def) - float(league_def)))
    if home_recent_offense is not None and away_recent_offense is not None and league_recent_offense is not None:
        matchup_adjustment += 0.06 * ((float(home_recent_offense) - float(league_recent_offense)) + (float(away_recent_offense) - float(league_recent_offense)))
    if home_recent_allowed is not None and away_recent_allowed is not None and league_recent_allowed is not None:
        matchup_adjustment += 0.06 * ((float(home_recent_allowed) - float(league_recent_allowed)) + (float(away_recent_allowed) - float(league_recent_allowed)))
    matchup_adjustment = float(max(-8.0, min(8.0, matchup_adjustment)))

    matchup_margin_adjustment = 0.0
    if home_off is not None and away_off is not None:
        matchup_margin_adjustment += 0.12 * (float(home_off) - float(away_off))
    if home_def is not None and away_def is not None:
        matchup_margin_adjustment += 0.10 * (float(away_def) - float(home_def))
    if home_recent_offense is not None and away_recent_offense is not None:
        matchup_margin_adjustment += 0.07 * (float(home_recent_offense) - float(away_recent_offense))
    if home_recent_allowed is not None and away_recent_allowed is not None:
        matchup_margin_adjustment += 0.07 * (float(away_recent_allowed) - float(home_recent_allowed))
    matchup_margin_adjustment = float(max(-6.0, min(6.0, matchup_margin_adjustment)))

    adjusted_margin = prop_blended_margin if prop_blended_margin is not None else raw_margin
    if adjusted_margin is not None:
        adjusted_margin = float(adjusted_margin) + float(matchup_margin_adjustment)
        if raw_margin is not None:
            adjusted_margin = float(max(float(raw_margin) - 7.0, min(float(raw_margin) + 7.0, float(adjusted_margin))))

    adjusted_total = prop_blended_total
    if adjusted_total is not None:
        adjusted_total = float(adjusted_total) + float(matchup_adjustment)
        if market_total is not None:
            adjusted_total = float((0.90 * float(adjusted_total)) + (0.10 * float(market_total)))
        if raw_total is not None:
            adjusted_total = float(max(float(raw_total) - 12.0, min(float(raw_total) + 12.0, float(adjusted_total))))

    home_adjusted_total = home_prop_blend
    away_adjusted_total = away_prop_blend
    if adjusted_total is not None and adjusted_margin is not None:
        home_adjusted_total = float(0.5 * (float(adjusted_total) + float(adjusted_margin)))
        away_adjusted_total = float(0.5 * (float(adjusted_total) - float(adjusted_margin)))

    return {
        "raw_margin": raw_margin,
        "raw_total": raw_total,
        "home_base_total": home_base,
        "away_base_total": away_base,
        "home_prop_total": home_prop_total,
        "away_prop_total": away_prop_total,
        "home_prop_blend": home_prop_blend,
        "away_prop_blend": away_prop_blend,
        "home_adjusted_total": home_adjusted_total,
        "away_adjusted_total": away_adjusted_total,
        "prop_blended_margin": prop_blended_margin,
        "prop_blended_total": prop_blended_total,
        "matchup_margin_adjustment": matchup_margin_adjustment,
        "adjusted_margin": adjusted_margin,
        "matchup_adjustment": matchup_adjustment,
        "adjusted_total": adjusted_total,
        "pace_gap": pace_gap,
        "home_prop_weight": home_prop_weight,
        "away_prop_weight": away_prop_weight,
    }


def _best_bets_margin_to_home_win_prob(
    margin: float | None,
    raw_home_win_prob: float | None = None,
) -> float | None:
    if margin is None and raw_home_win_prob is None:
        return None

    spread_prob = None
    if margin is not None:
        try:
            spread_prob = 1.0 / (1.0 + math.exp(-float(margin) / 6.0))
        except Exception:
            spread_prob = None

    out = spread_prob
    if raw_home_win_prob is not None and spread_prob is not None:
        out = (0.75 * float(raw_home_win_prob)) + (0.25 * float(spread_prob))
    elif raw_home_win_prob is not None:
        out = float(raw_home_win_prob)

    if out is None:
        return None
    return float(max(0.03, min(0.97, float(out))))


def _load_best_bets_game_context(date_str: str) -> dict[str, Any]:
    path = _find_predictions_for_date(date_str)
    df = _read_csv_if_exists(path)
    by_pair: dict[tuple[str, str], dict[str, Any]] = {}
    by_team: dict[str, dict[str, Any]] = {}
    total_vals: list[float] = []
    if not isinstance(df, pd.DataFrame) or df is None or df.empty:
        return {"by_pair": by_pair, "by_team": by_team, "slate_total_median": None}

    recent_offense_avgs, _recent_offense_ranks = _compute_team_offense_stats(date_str)
    allowed_avgs, _allowed_ranks = _compute_team_allowed_stats(date_str)
    team_advanced = _load_team_advanced_stats_frame(date_str)
    props_team_scoring = _load_best_bets_props_team_scoring_context(date_str)

    advanced_by_team: dict[str, dict[str, float | None]] = {}
    league_advanced: dict[str, float | None] = {"pace": None, "off_rtg": None, "def_rtg": None}
    if isinstance(team_advanced, pd.DataFrame) and not team_advanced.empty:
        for _, adv_row in team_advanced.iterrows():
            team_key = str(adv_row.get("team") or "").strip().upper()
            if not team_key:
                continue
            advanced_by_team[team_key] = {
                "pace": _safe_float(adv_row.get("pace")),
                "off_rtg": _safe_float(adv_row.get("off_rtg")),
                "def_rtg": _safe_float(adv_row.get("def_rtg")),
            }
        for col in ("pace", "off_rtg", "def_rtg"):
            if col not in team_advanced.columns:
                continue
            series = pd.to_numeric(team_advanced[col], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
            if not series.empty:
                league_advanced[col] = float(series.mean())

    recent_allowed_pts: dict[str, float] = {}
    for team_key, stats in (allowed_avgs or {}).items():
        pts_allowed = _safe_float((stats or {}).get("pts"))
        if pts_allowed is None:
            continue
        recent_allowed_pts[str(team_key or "").strip().upper()] = float(pts_allowed)

    league_recent_offense = None
    recent_offense_vals = [float(v) for v in (recent_offense_avgs or {}).values() if v is not None and np.isfinite(float(v))]
    if recent_offense_vals:
        league_recent_offense = float(np.mean(recent_offense_vals))

    league_recent_allowed = None
    recent_allowed_vals = [float(v) for v in recent_allowed_pts.values() if v is not None and np.isfinite(float(v))]
    if recent_allowed_vals:
        league_recent_allowed = float(np.mean(recent_allowed_vals))

    for _, r in df.iterrows():
        home = str(r.get("home_team") or r.get("home") or "").strip()
        away = str(r.get("visitor_team") or r.get("away_team") or r.get("away") or "").strip()
        if not home or not away:
            continue
        home_tri = (_get_tricode(home) or home.strip().upper())
        away_tri = (_get_tricode(away) or away.strip().upper())
        home_adv = _best_bets_team_lookup(advanced_by_team, home_tri, home) or {}
        away_adv = _best_bets_team_lookup(advanced_by_team, away_tri, away) or {}

        home_pace = _safe_float((home_adv or {}).get("pace"))
        away_pace = _safe_float((away_adv or {}).get("pace"))
        game_pace = None
        try:
            if home_pace is not None and away_pace is not None:
                game_pace = float(0.5 * (float(home_pace) + float(away_pace)))
        except Exception:
            game_pace = None

        raw_margin = _safe_float(r.get("spread_margin") if r.get("spread_margin") is not None else r.get("pred_margin"))
        raw_total = _safe_float(r.get("totals") if r.get("totals") is not None else r.get("pred_total"))
        market_total = _safe_float(r.get("total"))
        home_recent_offense = _safe_float(_best_bets_team_lookup(recent_offense_avgs, home_tri, home))
        away_recent_offense = _safe_float(_best_bets_team_lookup(recent_offense_avgs, away_tri, away))
        home_recent_allowed = _safe_float(_best_bets_team_lookup(recent_allowed_pts, home_tri, home))
        away_recent_allowed = _safe_float(_best_bets_team_lookup(recent_allowed_pts, away_tri, away))
        total_parts = _best_bets_adjust_matchup_total(
            raw_total=raw_total,
            raw_margin=raw_margin,
            market_total=market_total,
            home_prop_ctx=props_team_scoring.get(home_tri),
            away_prop_ctx=props_team_scoring.get(away_tri),
            home_off=_safe_float((home_adv or {}).get("off_rtg")),
            away_off=_safe_float((away_adv or {}).get("off_rtg")),
            home_def=_safe_float((home_adv or {}).get("def_rtg")),
            away_def=_safe_float((away_adv or {}).get("def_rtg")),
            league_off=_safe_float(league_advanced.get("off_rtg")),
            league_def=_safe_float(league_advanced.get("def_rtg")),
            home_recent_offense=home_recent_offense,
            away_recent_offense=away_recent_offense,
            home_recent_allowed=home_recent_allowed,
            away_recent_allowed=away_recent_allowed,
            league_recent_offense=league_recent_offense,
            league_recent_allowed=league_recent_allowed,
            game_pace=game_pace,
            league_pace=_safe_float(league_advanced.get("pace")),
        )
        adjusted_total = _safe_float(total_parts.get("adjusted_total"))
        adjusted_margin = _safe_float(total_parts.get("adjusted_margin"))
        raw_home_win_prob = _safe_float(
            r.get("home_win_prob_cal")
            if r.get("home_win_prob_cal") is not None
            else (r.get("home_win_prob") if r.get("home_win_prob") is not None else r.get("home_win_prob_iso"))
        )
        adjusted_home_win_prob = _best_bets_margin_to_home_win_prob(adjusted_margin, raw_home_win_prob)
        if adjusted_total is not None:
            total_vals.append(float(adjusted_total))
        elif raw_total is not None:
            total_vals.append(float(raw_total))
        ctx = {
            "home_team": home,
            "away_team": away,
            "home_tri": home_tri,
            "away_tri": away_tri,
            "pred_margin": adjusted_margin if adjusted_margin is not None else raw_margin,
            "pred_margin_raw": raw_margin,
            "pred_margin_adjusted": adjusted_margin,
            "pred_margin_prop_blend": _safe_float(total_parts.get("prop_blended_margin")),
            "pred_margin_matchup_adjustment": _safe_float(total_parts.get("matchup_margin_adjustment")),
            "pred_total": adjusted_total if adjusted_total is not None else raw_total,
            "pred_total_raw": raw_total,
            "pred_total_adjusted": adjusted_total,
            "pred_total_prop_blend": _safe_float(total_parts.get("prop_blended_total")),
            "pred_total_matchup_adjustment": _safe_float(total_parts.get("matchup_adjustment")),
            "pred_total_pace_gap": _safe_float(total_parts.get("pace_gap")),
            "home_pred_points": _safe_float(total_parts.get("home_adjusted_total")) if _safe_float(total_parts.get("home_adjusted_total")) is not None else (_safe_float(total_parts.get("home_prop_blend")) if _safe_float(total_parts.get("home_prop_blend")) is not None else _safe_float(total_parts.get("home_base_total"))),
            "away_pred_points": _safe_float(total_parts.get("away_adjusted_total")) if _safe_float(total_parts.get("away_adjusted_total")) is not None else (_safe_float(total_parts.get("away_prop_blend")) if _safe_float(total_parts.get("away_prop_blend")) is not None else _safe_float(total_parts.get("away_base_total"))),
            "home_win_prob": adjusted_home_win_prob if adjusted_home_win_prob is not None else raw_home_win_prob,
            "home_win_prob_raw": raw_home_win_prob,
            "home_win_prob_adjusted": adjusted_home_win_prob,
            "commence_time": r.get("commence_time") if r.get("commence_time") not in (None, "") else r.get("start_time"),
            "home_ml": _safe_float(r.get("home_ml")),
            "away_ml": _safe_float(r.get("away_ml")),
            "home_spread": _safe_float(r.get("home_spread")),
            "away_spread": _safe_float(r.get("away_spread")),
            "market_total": market_total,
            "league_pace": _safe_float(league_advanced.get("pace")),
            "league_off_rtg": _safe_float(league_advanced.get("off_rtg")),
            "league_def_rtg": _safe_float(league_advanced.get("def_rtg")),
            "home_pace": home_pace,
            "away_pace": away_pace,
            "game_pace": game_pace,
            "home_off_rtg": _safe_float((home_adv or {}).get("off_rtg")),
            "home_def_rtg": _safe_float((home_adv or {}).get("def_rtg")),
            "away_off_rtg": _safe_float((away_adv or {}).get("off_rtg")),
            "away_def_rtg": _safe_float((away_adv or {}).get("def_rtg")),
            "home_recent_offense": home_recent_offense,
            "away_recent_offense": away_recent_offense,
            "home_recent_allowed_pts": home_recent_allowed,
            "away_recent_allowed_pts": away_recent_allowed,
            "league_recent_offense": league_recent_offense,
            "league_recent_allowed_pts": league_recent_allowed,
            "home_prop_points_sum": _safe_float((props_team_scoring.get(home_tri) or {}).get("points_sum")),
            "away_prop_points_sum": _safe_float((props_team_scoring.get(away_tri) or {}).get("points_sum")),
            "home_prop_minutes_coverage": _safe_float((props_team_scoring.get(home_tri) or {}).get("minutes_coverage")),
            "away_prop_minutes_coverage": _safe_float((props_team_scoring.get(away_tri) or {}).get("minutes_coverage")),
            "home_prop_blend_weight": _safe_float((props_team_scoring.get(home_tri) or {}).get("blend_weight")),
            "away_prop_blend_weight": _safe_float((props_team_scoring.get(away_tri) or {}).get("blend_weight")),
        }
        for key in {
            (home.upper(), away.upper()),
            (home_tri.upper(), away_tri.upper()),
        }:
            by_pair[key] = ctx
        for key in {home.upper(), away.upper(), home_tri.upper(), away_tri.upper()}:
            by_team[key] = ctx

    slate_total_median = None
    if total_vals:
        try:
            slate_total_median = float(np.median(total_vals))
        except Exception:
            slate_total_median = None
    return {"by_pair": by_pair, "by_team": by_team, "slate_total_median": slate_total_median}


def _best_bets_ctx_for_matchup(
    game_context: dict[str, Any] | None,
    *,
    home: Any,
    away: Any,
) -> dict[str, Any] | None:
    if not isinstance(game_context, dict):
        return None
    by_pair = game_context.get("by_pair") if isinstance(game_context.get("by_pair"), dict) else {}
    by_team = game_context.get("by_team") if isinstance(game_context.get("by_team"), dict) else {}

    home_name = str(home or "").strip()
    away_name = str(away or "").strip()
    home_tri = (_get_tricode(home_name) or home_name.upper()) if home_name else ""
    away_tri = (_get_tricode(away_name) or away_name.upper()) if away_name else ""

    for key in (
        (home_name.upper(), away_name.upper()),
        (home_tri.upper(), away_tri.upper()),
    ):
        if key in by_pair and isinstance(by_pair.get(key), dict):
            return by_pair.get(key)

    for key in (home_name.upper(), away_name.upper(), home_tri.upper(), away_tri.upper()):
        if key in by_team and isinstance(by_team.get(key), dict):
            return by_team.get(key)
    return None


def _live_pregame_prior_for_matchup(
    game_context: dict[str, Any] | None,
    *,
    home: Any,
    away: Any,
) -> dict[str, Any] | None:
    ctx = _best_bets_ctx_for_matchup(game_context, home=home, away=away)
    if not isinstance(ctx, dict):
        return None

    out: dict[str, Any] = {}
    for key in (
        "home_team",
        "away_team",
        "home_tri",
        "away_tri",
        "pred_total",
        "pred_total_raw",
        "pred_total_adjusted",
        "pred_total_prop_blend",
        "pred_total_matchup_adjustment",
        "pred_margin",
        "pred_margin_raw",
        "pred_margin_adjusted",
        "pred_margin_prop_blend",
        "pred_margin_matchup_adjustment",
        "home_win_prob",
        "home_win_prob_raw",
        "home_win_prob_adjusted",
        "home_pred_points",
        "away_pred_points",
        "market_total",
        "commence_time",
        "game_pace",
        "league_pace",
        "home_off_rtg",
        "away_off_rtg",
        "home_def_rtg",
        "away_def_rtg",
        "home_recent_offense",
        "away_recent_offense",
        "home_recent_allowed_pts",
        "away_recent_allowed_pts",
        "home_prop_minutes_coverage",
        "away_prop_minutes_coverage",
        "home_prop_blend_weight",
        "away_prop_blend_weight",
    ):
        value = ctx.get(key)
        if value is not None:
            out[key] = value
    return out or None


def _live_team_pregame_prior_for_matchup(
    game_context: dict[str, Any] | None,
    *,
    home: Any,
    away: Any,
    team: Any,
) -> dict[str, Any] | None:
    prior = _live_pregame_prior_for_matchup(game_context, home=home, away=away)
    if not isinstance(prior, dict):
        return None

    team_key = (_get_tricode(str(team or "")) or str(team or "").strip().upper()) if team is not None else ""
    home_key = (_get_tricode(str(prior.get("home_tri") or prior.get("home_team") or home or "")) or str(prior.get("home_tri") or prior.get("home_team") or home or "").strip().upper())
    away_key = (_get_tricode(str(prior.get("away_tri") or prior.get("away_team") or away or "")) or str(prior.get("away_tri") or prior.get("away_team") or away or "").strip().upper())
    if not team_key or team_key not in {home_key, away_key}:
        return None

    raw_total = _safe_float(prior.get("pred_total_raw"))
    adjusted_total = _safe_float(prior.get("pred_total_adjusted"))
    if adjusted_total is None:
        adjusted_total = _safe_float(prior.get("pred_total"))
    raw_margin = _safe_float(prior.get("pred_margin_raw"))
    adjusted_margin = _safe_float(prior.get("pred_margin_adjusted"))
    if adjusted_margin is None:
        adjusted_margin = _safe_float(prior.get("pred_margin"))

    raw_home_total = None
    raw_away_total = None
    if raw_total is not None and raw_margin is not None:
        try:
            raw_home_total = 0.5 * (float(raw_total) + float(raw_margin))
            raw_away_total = 0.5 * (float(raw_total) - float(raw_margin))
        except Exception:
            raw_home_total = None
            raw_away_total = None

    if team_key == home_key:
        team_side = "home"
        team_points_adjusted = _safe_float(prior.get("home_pred_points"))
        team_points_raw = raw_home_total
        team_margin_raw = raw_margin
        team_margin_adjusted = adjusted_margin
    else:
        team_side = "away"
        team_points_adjusted = _safe_float(prior.get("away_pred_points"))
        team_points_raw = raw_away_total
        team_margin_raw = None if raw_margin is None else -float(raw_margin)
        team_margin_adjusted = None if adjusted_margin is None else -float(adjusted_margin)

    game_total_ratio = None
    if adjusted_total is not None and raw_total is not None and float(raw_total) > 1e-6:
        try:
            game_total_ratio = float(max(0.88, min(1.12, float(adjusted_total) / float(raw_total))))
        except Exception:
            game_total_ratio = None

    team_total_ratio = None
    if team_points_adjusted is not None and team_points_raw is not None and float(team_points_raw) > 1e-6:
        try:
            team_total_ratio = float(max(0.85, min(1.18, float(team_points_adjusted) / float(team_points_raw))))
        except Exception:
            team_total_ratio = None

    return {
        "team_side": team_side,
        "game_total_raw": raw_total,
        "game_total_adjusted": adjusted_total,
        "game_total_ratio": game_total_ratio,
        "team_pred_points_raw": team_points_raw,
        "team_pred_points_adjusted": team_points_adjusted,
        "team_total_ratio": team_total_ratio,
        "team_margin_raw": team_margin_raw,
        "team_margin_adjusted": team_margin_adjusted,
    }


def _live_player_prop_pregame_multiplier(team_prior: dict[str, Any] | None, stat_key: Any) -> float | None:
    if not isinstance(team_prior, dict):
        return None
    stat = _live_stat_key(stat_key)
    team_ratio = _safe_float(team_prior.get("team_total_ratio"))
    game_ratio = _safe_float(team_prior.get("game_total_ratio"))
    if team_ratio is None and game_ratio is None:
        return None

    base = None
    if stat == "pts":
        base = team_ratio
    elif stat == "ast" and team_ratio is not None:
        base = 1.0 + 0.75 * (float(team_ratio) - 1.0)
    elif stat == "threes" and team_ratio is not None:
        base = 1.0 + 1.05 * (float(team_ratio) - 1.0)
    elif stat == "pra" and team_ratio is not None:
        base = 1.0 + 0.90 * (float(team_ratio) - 1.0)
    elif stat == "reb" and game_ratio is not None:
        base = 1.0 + 0.35 * (float(game_ratio) - 1.0)
    elif stat == "tov" and team_ratio is not None:
        base = 1.0 + 0.40 * (float(team_ratio) - 1.0)
    elif stat in {"stl", "blk"} and game_ratio is not None:
        base = 1.0 + 0.25 * (float(game_ratio) - 1.0)
    if base is None:
        return None
    try:
        return float(max(0.85, min(1.18, float(base))))
    except Exception:
        return None


def _ll_tag_is_meta(tag: str) -> bool:
    t = str(tag or "").strip().lower()
    return t.startswith("market:") or t.startswith("horizon:") or t.startswith("klass:") or t.startswith("stat:")


def _ll_tag_type(tag: str) -> str:
    try:
        t = str(tag or "").strip().lower()
        if ":" in t:
            return t.split(":", 1)[0]
        return t
    except Exception:
        return ""


def _ll_driver_from_type(tag_type: str) -> str:
    t = str(tag_type or "").strip().lower()
    if not t:
        return ""
    if t in {"injury"}:
        return "injury"
    if t in {"rot", "rot_off"}:
        return "rotation"
    if t in {"pf"}:
        return "foul_trouble"
    if t in {"proj_min", "rem_min", "mp"}:
        return "minutes"
    if t in {"sim"}:
        return "sim"
    if t in {"risk", "support"}:
        return "adjustment"
    if t in {"line_src", "line_age", "books", "market_span", "hold", "bettable", "bet_score", "gate"}:
        return "market_quality"
    if t in {"edge_sigma"}:
        return "signal_strength"
    if t in {"pace_mult", "role_mult", "hot", "foul_adj"}:
        return "player_adjustment"
    if t in {"shrink"}:
        return "shrink"
    if t in {"interval_drift", "interval_drift_mag"}:
        return "interval_drift"
    if t in {"recent_window", "recent_window_w"}:
        return "recent_window"
    if t in {"endgame_foul", "endgame_foul_mag"}:
        return "endgame_foul"
    if t in {"time"}:
        return "time"
    if t in {"mgn"}:
        return "margin"
    if t in {"pace", "poss", "ppp"}:
        return "pace_eff"
    if t in {"spr", "ats_side"}:
        return "spread"
    if t in {"ctx", "scope"}:
        return "context"
    return t


def _ll_load_audit_module():
    # EDIT: the vendored tools/daily_live_lens_audit.py, ported as .live_lens_audit (closure only).
    from . import live_lens_audit as _audit

    return _audit


def _ll_enrich_signal_tags(body: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(body, dict):
        return body
    obj = dict(body)
    try:
        audit = _ll_load_audit_module()
        market = str(obj.get("market") or "").strip().lower()
        if not market:
            return obj

        horizon = str(obj.get("horizon") or "").strip().lower() or None
        klass = str(obj.get("klass") or "").strip().upper() or None

        stat_key = None
        if market == "player_prop":
            try:
                stat_key = str(obj.get("stat") or "").strip().lower() or None
            except Exception:
                stat_key = None
            try:
                if stat_key:
                    stat_key = str(audit._live_stat_key(stat_key))
            except Exception:
                pass

        interval_on = recent_on = foul_on = None
        try:
            interval_on, recent_on, foul_on = audit._flag_adjustments(obj.get("context"))
        except Exception:
            interval_on, recent_on, foul_on = None, None, None

        tags = audit._derive_tags(
            obj=obj,
            market=market,
            horizon=horizon,
            klass=klass,
            stat_key=stat_key,
            interval_drift_on=interval_on,
            recent_window_on=recent_on,
            endgame_foul_on=foul_on,
        )
        tags = tags if isinstance(tags, list) else ([] if tags is None else [str(tags)])
        tags = [str(t) for t in tags if t is not None and str(t).strip()]
        if not tags:
            return obj

        driver_tags = [t for t in tags if not _ll_tag_is_meta(t)]
        driver_types = sorted({t for t in (_ll_tag_type(x) for x in driver_tags) if t})
        drivers = sorted({_ll_driver_from_type(t) for t in driver_types if t})

        obj["tags"] = tags
        obj["driver_tags"] = driver_tags
        if driver_types:
            obj["driver_types"] = driver_types
        if drivers:
            obj["drivers"] = drivers
            obj["driver"] = drivers[0]
    except Exception:
        return obj
    return obj


def _espn_to_tri(abbr: str) -> str:
    s = str(abbr or '').upper().strip()
    is_wnba = "wnba" in str(getattr(LEAGUE, 'espn_sport_path', '') or '').lower()
    if is_wnba:
        fix = {
            'GS': 'GSV',
            'GSW': 'GSV',
            'LAS': 'LA',
            'LV': 'LVA',
            'NY': 'NYL',
            'NYK': 'NYL',
            'WAS': 'WSH',
        }
    else:
        fix = {
            'GS': 'GSW',
            'NO': 'NOP',
            'NY': 'NYK',
            'BRK': 'BKN',
            'BK': 'BKN',
            'PHO': 'PHX',
            # ESPN sometimes uses legacy or short abbreviations that don't match league tricodes
            'SA': 'SAS',
            'WSH': 'WAS',
            'UTAH': 'UTA',
        }
    return fix.get(s, s)


def _fetch_espn_scoreboard(date_str_local: str) -> Optional[dict[str, Any]]:
    try:
        import requests as _rq  # type: ignore
    except Exception:
        return None
    try:
        ymd = date_str_local.replace('-', '')
        url = f"https://site.web.api.espn.com/apis/site/v2/{getattr(LEAGUE, 'espn_sport_path', 'sports/basketball/wnba')}/scoreboard?dates={ymd}"
        headers = {
            "Accept": "application/json, text/plain, */*",
            "Accept-Language": "en-US,en;q=0.9",
            "Cache-Control": "no-cache",
            "Pragma": "no-cache",
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/125.0.0.0 Safari/537.36"
            ),
            "Referer": "https://www.espn.com/",
        }
        try:
            sess = _rq.Session()
            sess.trust_env = False
            r = sess.get(url, headers=headers, timeout=8)
        except Exception:
            r = _rq.get(url, headers=headers, timeout=8)
        if r.status_code != 200:
            return None
        jd = r.json()
        return jd if isinstance(jd, dict) else None
    except Exception:
        return None


def _parse_ttl_param(req, default: int, lo: int = 1, hi: int = 3600) -> int:
    try:
        v = req.args.get("ttl")
        if v is None:
            return int(default)
        x = int(float(str(v).strip()))
        if x < lo:
            return int(lo)
        if x > hi:
            return int(hi)
        return int(x)
    except Exception:
        return int(default)


def _live_game_elapsed_minutes(period: int | None, clock: Any, is_final: bool) -> float | None:
    """Compute elapsed regulation minutes from period + clock.

    Mirrors client-side logic using league-configured regulation timing.
    """
    try:
        regulation_period_sec = int(getattr(LEAGUE, "regulation_period_seconds", 12 * 60) or 12 * 60)
        regulation_game_min = max(1.0, float(getattr(LEAGUE, "regulation_team_minutes", 240.0)) / 5.0)
        if is_final:
            return regulation_game_min
        if period is None:
            return None
        p = int(period)
        if p < 1:
            return None
        if p > 4:
            return regulation_game_min
        sec_left = _live_parse_clock_to_sec_left(clock)
        if sec_left is None:
            return None
        elapsed_sec = ((p - 1) * regulation_period_sec) + max(0, (regulation_period_sec - int(sec_left)))
        return float(max(0.0, min(regulation_game_min, elapsed_sec / 60.0)))
    except Exception:
        return None


def _live_find_processed_csv(stem_prefix: str, date_str: str) -> Path | None:
    try:
        proc = DATA_PROCESSED_DIR
        p = proc / f"{stem_prefix}_{date_str}.csv"
        return p if p.exists() else None
    except Exception:
        return None


def _live_load_period_lines_map(date_str: str) -> dict[tuple[str, str], dict[str, Any]]:
    """Load period lines (1H + Q1..Q4 totals/spreads) from processed CSV.

    Expected file: data/processed/period_lines_<date>.csv

    Returns a map keyed by (HOME_TRI, AWAY_TRI) with:
      {
        "period_totals": {"h1": float|None, "q1": float|None, ...},
        "period_spreads": {"h1": float|None, "q1": float|None, ...},
      }
    """
    def _to_tri_best(x: Any) -> str:
        s = str(x or "").strip()
        if not s:
            return ""
        try:
            if _to_tricode is not None:
                return str(_to_tricode(s) or "").strip().upper()
        except Exception:
            pass
        try:
            t = _get_tricode(s)
            return str(t or "").strip().upper()
        except Exception:
            return s.upper()

    def _build_map_from_df(df: pd.DataFrame) -> dict[tuple[str, str], dict[str, Any]]:
        if df is None or df.empty:
            return {}

        cols = {str(c).strip().lower(): str(c) for c in df.columns}
        home_col = cols.get("home_team")
        away_col = cols.get("visitor_team") or cols.get("away_team")
        if not (home_col and away_col):
            return {}

        def _col(name: str) -> str | None:
            return cols.get(name)

        out: dict[tuple[str, str], dict[str, Any]] = {}
        for _, r in df.iterrows():
            try:
                htri = _to_tri_best(r.get(home_col))
                atri = _to_tri_best(r.get(away_col))
                if not htri or not atri:
                    continue

                period_totals = {
                    "h1": _safe_float(r.get(_col("h1_total")) if _col("h1_total") else None),
                    "q1": _safe_float(r.get(_col("q1_total")) if _col("q1_total") else None),
                    "q2": _safe_float(r.get(_col("q2_total")) if _col("q2_total") else None),
                    "q3": _safe_float(r.get(_col("q3_total")) if _col("q3_total") else None),
                    "q4": _safe_float(r.get(_col("q4_total")) if _col("q4_total") else None),
                }
                period_spreads = {
                    "h1": _safe_float(r.get(_col("h1_spread")) if _col("h1_spread") else None),
                    "q1": _safe_float(r.get(_col("q1_spread")) if _col("q1_spread") else None),
                    "q2": _safe_float(r.get(_col("q2_spread")) if _col("q2_spread") else None),
                    "q3": _safe_float(r.get(_col("q3_spread")) if _col("q3_spread") else None),
                    "q4": _safe_float(r.get(_col("q4_spread")) if _col("q4_spread") else None),
                }

                out[(htri, atri)] = {"period_totals": period_totals, "period_spreads": period_spreads}
            except Exception:
                continue
        return out

    p = _live_find_processed_csv("period_lines", date_str)
    if not p:
        try:
            from .odds_bovada import fetch_bovada_period_lines_current as _fbplc  # type: ignore

            live_df = _fbplc(date_str)
            return _build_map_from_df(live_df if isinstance(live_df, pd.DataFrame) else pd.DataFrame())
        except Exception:
            return {}
    try:
        mtime = int(p.stat().st_mtime)
    except Exception:
        mtime = 0

    cache_key = f"period_lines:{date_str}:{mtime}"
    ent = _live_processed_cache.get(cache_key)
    if ent is not None:
        try:
            return ent[1]  # type: ignore[return-value]
        except Exception:
            pass

    try:
        df = pd.read_csv(p)
        if df is None or df.empty:
            _live_processed_cache[cache_key] = (mtime, {})
            return {}
        out = _build_map_from_df(df)

        _live_processed_cache[cache_key] = (mtime, out)
        return out
    except Exception:
        _live_processed_cache[cache_key] = (mtime, {})
        return {}


def _live_stat_key(x: Any) -> str:
    s = str(x or "").strip().lower()
    m = {
        "points": "pts",
        "point": "pts",
        "pts": "pts",
        "rebounds": "reb",
        "rebound": "reb",
        "reb": "reb",
        "assists": "ast",
        "assist": "ast",
        "ast": "ast",
        "3pt": "threes",
        "3pm": "threes",
        "threes": "threes",
        "threes_made": "threes",
        "pra": "pra",
        "points+rebounds+assists": "pra",
        "turnovers": "tov",
        "tov": "tov",
        "steals": "stl",
        "stl": "stl",
        "blocks": "blk",
        "blk": "blk",
    }
    return m.get(s, s)


def _live_load_props_edges_index(date_str: str) -> dict[tuple[str, str, str], float]:
    """Return map (TEAM_TRI, NAME_KEY, STAT_KEY) -> pregame line (median across offers)."""
    p = _live_find_processed_csv("props_edges", date_str)
    if not p:
        return {}
    try:
        mtime = int(p.stat().st_mtime)
    except Exception:
        mtime = 0
    cache_key = f"props_edges:{date_str}:{mtime}"
    ent = _live_processed_cache.get(cache_key)
    if ent is not None:
        try:
            return ent[1]  # type: ignore[return-value]
        except Exception:
            pass
    try:
        df = pd.read_csv(p)
        if df is None or df.empty:
            _live_processed_cache[cache_key] = (mtime, {})
            return {}
        cols = {c.lower(): c for c in df.columns}
        need = [cols.get("team"), cols.get("player_name"), cols.get("stat"), cols.get("line")]
        if not all(need):
            _live_processed_cache[cache_key] = (mtime, {})
            return {}
        tcol = cols["team"]
        ncol = cols["player_name"]
        scol = cols["stat"]
        lcol = cols["line"]
        tmp = df[[tcol, ncol, scol, lcol]].copy()
        tmp[tcol] = tmp[tcol].astype(str).str.strip().str.upper()
        tmp["_name_key"] = tmp[ncol].astype(str).map(_norm_player_name)
        tmp["_stat_key"] = tmp[scol].map(_live_stat_key)
        tmp["_line"] = pd.to_numeric(tmp[lcol], errors="coerce")
        tmp = tmp.dropna(subset=["_line"]).copy()
        if tmp.empty:
            _live_processed_cache[cache_key] = (mtime, {})
            return {}

        out: dict[tuple[str, str, str], float] = {}
        grp = tmp.groupby([tcol, "_name_key", "_stat_key"], dropna=True)
        for (team, name_key, stat_key), g in grp:
            try:
                if not team or not name_key or not stat_key:
                    continue
                lines = pd.to_numeric(g["_line"], errors="coerce").dropna()
                if lines.empty:
                    continue
                out[(str(team), str(name_key), str(stat_key))] = float(lines.median())
            except Exception:
                continue

        _live_processed_cache[cache_key] = (mtime, out)
        return out
    except Exception:
        _live_processed_cache[cache_key] = (mtime, {})
        return {}


def _live_load_props_recommendations_line_index(date_str: str) -> dict[tuple[str, str, str], float]:
    """Return map (TEAM_TRI, NAME_KEY, STAT_KEY) -> pregame line derived from props_recommendations.

    This is a fallback when props_edges_YYYY-MM-DD.csv is missing.
    """
    p = _live_find_processed_csv("props_recommendations", date_str)
    if not p:
        return {}
    try:
        mtime = int(p.stat().st_mtime)
    except Exception:
        mtime = 0
    cache_key = f"props_recommendations_lines:{date_str}:{mtime}"
    ent = _live_processed_cache.get(cache_key)
    if ent is not None:
        try:
            return ent[1]  # type: ignore[return-value]
        except Exception:
            pass

    try:
        df = pd.read_csv(p)
        if df is None or df.empty:
            _live_processed_cache[cache_key] = (mtime, {})
            return {}

        cols = {c.lower(): c for c in df.columns}
        tcol = cols.get("team")
        pcol = cols.get("player") or cols.get("player_name")
        plays_col = cols.get("plays")
        if not (tcol and pcol and plays_col):
            _live_processed_cache[cache_key] = (mtime, {})
            return {}

        import ast

        def _parse_plays(x: Any) -> list[dict[str, Any]]:
            try:
                if x is None:
                    return []
                if isinstance(x, float) and np.isnan(x):
                    return []
                s = str(x).strip()
                if not s or s.lower() == "nan":
                    return []
                v = ast.literal_eval(s)
                if not isinstance(v, list):
                    return []
                outv: list[dict[str, Any]] = []
                for it in v:
                    if isinstance(it, dict):
                        outv.append(it)
                return outv
            except Exception:
                return []

        accum: dict[tuple[str, str, str], list[float]] = {}
        tmp = df[[tcol, pcol, plays_col]].copy()
        tmp[tcol] = tmp[tcol].astype(str).str.strip().str.upper()
        tmp["_name_key"] = tmp[pcol].astype(str).map(_norm_player_name)

        for _, r in tmp.iterrows():
            try:
                team = str(r.get(tcol) or "").strip().upper()
                nk = str(r.get("_name_key") or "").strip().upper()
                if not team or not nk:
                    continue
                plays = _parse_plays(r.get(plays_col))
                if not plays:
                    continue
                for pl in plays:
                    try:
                        stat_key = _live_stat_key(pl.get("market"))
                        if stat_key not in {"pts", "reb", "ast", "threes", "pra", "stl", "blk", "tov"}:
                            continue
                        ln = _safe_float(pl.get("line"))
                        if ln is None or not math.isfinite(float(ln)):
                            continue
                        accum.setdefault((team, nk, str(stat_key)), []).append(float(ln))
                    except Exception:
                        continue
            except Exception:
                continue

        out: dict[tuple[str, str, str], float] = {}
        for k, lines in (accum or {}).items():
            try:
                if not lines:
                    continue
                out[k] = float(np.median(np.asarray(lines, dtype=float)))
            except Exception:
                continue

        _live_processed_cache[cache_key] = (mtime, out)
        return out
    except Exception:
        _live_processed_cache[cache_key] = (mtime, {})
        return {}


def _live_load_props_predictions_index(date_str: str) -> dict[tuple[str, str], dict[str, Any]]:
    """Return map (TEAM_TRI, NAME_KEY) -> {mean_*, roll*_min, pred_*} dict."""
    p = _live_find_processed_csv("props_predictions", date_str)
    if not p:
        return {}
    try:
        mtime = int(p.stat().st_mtime)
    except Exception:
        mtime = 0
    cache_key = f"props_predictions:{date_str}:{mtime}"
    ent = _live_processed_cache.get(cache_key)
    if ent is not None:
        try:
            return ent[1]  # type: ignore[return-value]
        except Exception:
            pass
    try:
        df = pd.read_csv(p)
        if df is None or df.empty:
            _live_processed_cache[cache_key] = (mtime, {})
            return {}
        cols = {c.lower(): c for c in df.columns}
        tcol = cols.get("team")
        ncol = cols.get("player_name")
        if not (tcol and ncol):
            _live_processed_cache[cache_key] = (mtime, {})
            return {}

        # Keep only the columns we care about (best-effort; tolerate schema changes)
        keep = [tcol, ncol]
        for c in df.columns:
            cl = str(c).lower()
            if cl.startswith("mean_") or cl.startswith("pred_") or cl.startswith("roll") or cl in {"lag1_min"}:
                keep.append(c)
        keep = list(dict.fromkeys(keep))
        tmp = df[keep].copy()
        tmp[tcol] = tmp[tcol].astype(str).str.strip().str.upper()
        tmp["_name_key"] = tmp[ncol].astype(str).map(_norm_player_name)

        out: dict[tuple[str, str], dict[str, Any]] = {}
        for _, r in tmp.iterrows():
            try:
                team = str(r.get(tcol) or "").strip().upper()
                nk = str(r.get("_name_key") or "").strip().upper()
                if not team or not nk:
                    continue
                rec: dict[str, Any] = {}
                for k in keep:
                    if k in {tcol, ncol}:
                        continue
                    rec[str(k)] = r.get(k)
                out[(team, nk)] = rec
            except Exception:
                continue

        _live_processed_cache[cache_key] = (mtime, out)
        return out
    except Exception:
        _live_processed_cache[cache_key] = (mtime, {})
        return {}


@app.route("/api/live_pbp_stats")
def api_live_pbp_stats():
    """NCAAB-parity endpoint: PBP-derived stats for multiple ESPN event ids.

    Query params:
      - event_ids: comma-separated ESPN event ids (required)
      - ttl: seconds (optional)
      - date: YYYY-MM-DD (optional, used for mapping)
    """
    ttl = _parse_ttl_param(request, default=20, lo=1, hi=300)
    try:
        recent_window_sec = int(float((request.args.get("recent_window_sec") or "180").strip()))
    except Exception:
        recent_window_sec = 180
    recent_window_sec = int(max(10, min(600, recent_window_sec)))
    event_ids_raw = (request.args.get("event_ids") or "").strip()
    if not event_ids_raw:
        return jsonify({"error": "missing event_ids"}), 400
    event_ids = [x.strip() for x in event_ids_raw.split(",") if x.strip()]
    if not event_ids:
        return jsonify({"error": "missing event_ids"}), 400

    d = _parse_date_param(request, default_to_today=False) or ""
    now = time.time()
    cache_key = f"{d}:{ttl}:" + ",".join(event_ids)
    ent = _live_pbp_multi_cache.get(cache_key)
    if ent and (now - ent[0] < ttl):
        return jsonify(ent[1])

    # Best-effort mapping to SmartSim game_id + team tricodes
    games_map: dict[str, dict[str, Any]] = {}
    if d:
        try:
            _src, sb_games = _live_build_scoreboard_games(d)
            for g in sb_games or []:
                eid = str(g.get("espn_event_id") or "").strip()
                if eid:
                    games_map[eid] = g
        except Exception:
            games_map = {}

    out: list[dict[str, Any]] = []
    for eid in event_ids:
        g = games_map.get(str(eid))
        gid = (g.get("game_id") if isinstance(g, dict) else None)
        home = (g.get("home") if isinstance(g, dict) else None)
        away = (g.get("away") if isinstance(g, dict) else None)

        actions: list[dict[str, Any]] = []
        try:
            summ = _live_fetch_espn_summary(str(eid))
            actions = _live_espn_actions_from_summary(summ) if summ else []
        except Exception:
            actions = []

        pbp_attempts = _live_pbp_attempt_stats(actions) if actions else {"home": {}, "away": {}, "unknown": {}, "total": {}}
        pbp_attempts_periods = _live_pbp_attempt_stats_periods(actions) if actions else {}
        pbp_possessions = _live_pbp_possession_stats(actions, pbp_attempts) if actions else {"home": {}, "away": {}, "unknown": {}, "total": {}}
        pbp_possessions_periods = _live_pbp_possession_stats_periods(actions) if actions else {}
        pbp_quarters = _live_pbp_quarter_totals(actions) if actions else {"q_totals": {"q1": None, "q2": None, "q3": None, "q4": None}, "current": {"period": None, "q_total": None}}
        pbp_recent = _live_pbp_recent_window_stats(actions, window_sec=recent_window_sec) if actions else {"window_sec": recent_window_sec, "points_total": None, "attempts": None, "possessions": None}

        out.append({
            "event_id": str(eid),
            "game_id": gid,
            "home": home,
            "away": away,
            "pbp_attempts": pbp_attempts,
            "pbp_attempts_periods": pbp_attempts_periods,
            "pbp_possessions": pbp_possessions,
            "pbp_possessions_periods": pbp_possessions_periods,
            "pbp_quarters": pbp_quarters,
            "pbp_recent": pbp_recent,
        })

    payload = {
        "ok": True,
        "ttl": ttl,
        "games": out,
        "generated_at": datetime.utcnow().isoformat(timespec="seconds") + "Z",
    }

    # Optional persistence: snapshot PBP-derived stats used for decisions.
    _live_append_snapshot(
        "live_pbp_stats",
        d or "",
        {
            "ts": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "endpoint": "/api/live_pbp_stats",
            "query": {
                "date": d or None,
                "event_ids": event_ids,
                "recent_window_sec": recent_window_sec,
                "ttl": ttl,
            },
            "payload": payload,
        },
    )
    _live_pbp_multi_cache[cache_key] = (now, payload)
    return jsonify(payload)


@app.route("/api/live_player_lens")
def api_live_player_lens():
    """Merged live player lens: actual vs sim vs pregame line + pacing.

    Query params:
      - date: YYYY-MM-DD (optional but recommended; used to load processed props lines + sim means)
      - event_ids: comma-separated ESPN event ids (required)
      - ttl: seconds (optional)

    Response shape:
      { ok, ttl, date, games:[{event_id, game_id, home, away, status:{...}, rows:[...]}], generated_at }
    """
    ttl = _parse_ttl_param(request, default=20, lo=1, hi=300)
    include_all_prop_lines = str(
        request.args.get("include_all_prop_lines")
        if ("include_all_prop_lines" in request.args)
        else os.environ.get("LIVE_PLAYER_LENS_INCLUDE_ALL_PROP_LINES", "0")
    ).strip().lower() in {"1", "true", "yes"}
    include_debug_rows = str(
        request.args.get("include_debug_rows")
        if ("include_debug_rows" in request.args)
        else os.environ.get("LIVE_PLAYER_LENS_INCLUDE_DEBUG_ROWS", "0")
    ).strip().lower() in {"1", "true", "yes"}
    try:
        recent_window_sec = int(float((request.args.get("recent_window_sec") or "180").strip()))
    except Exception:
        recent_window_sec = 180
    recent_window_sec = int(max(10, min(600, recent_window_sec)))
    d = _parse_date_param(request, default_to_today=False) or ""
    event_ids_raw = (request.args.get("event_ids") or "").strip()
    if not event_ids_raw:
        # Backwards-compatible: if caller only provides date, infer event_ids from scoreboard.
        if not d:
            return jsonify({"error": "missing event_ids"}), 400
        try:
            _src, sb_games = _live_build_scoreboard_games(d)
            inferred_live = []
            inferred_all = []
            for g in sb_games or []:
                eid = str(g.get("espn_event_id") or g.get("game_id") or "").strip()
                if not eid:
                    continue
                inferred_all.append(eid)
                if bool(g.get("in_progress")) and not bool(g.get("final")):
                    inferred_live.append(eid)
            event_ids = inferred_live or inferred_all
        except Exception:
            event_ids = []
    else:
        event_ids = [x.strip() for x in event_ids_raw.split(",") if x.strip()]
    if not event_ids:
        return jsonify({"error": "missing event_ids"}), 400

    # Normalize cache key so the same set of games hits cache regardless of ordering.
    event_ids_for_key = sorted({str(x) for x in event_ids if str(x).strip()})
    if not event_ids_for_key:
        return jsonify({"error": "missing event_ids"}), 400

    now = time.time()
    cache_key = f"{d}:{ttl}:{recent_window_sec}:" + ",".join(event_ids_for_key)
    ent = _live_player_lens_multi_cache.get(cache_key)
    if ent and (now - ent[0] < ttl):
        return jsonify(ent[1])

    # Player prop signal thresholds (server-side) so each row can carry klass.
    player_prop_watch = 2.0
    player_prop_bet = 4.0

    # Optional: sigma-based thresholds (per-stat) for higher signal consistency.
    # These are opt-in so we can A/B against the legacy raw-strength thresholds.
    sigma_env_raw = os.environ.get("LIVE_PLAYER_LENS_SIGMA_THRESHOLDS")
    if sigma_env_raw is None or str(sigma_env_raw).strip() == "":
        use_sigma_thresholds: bool | None = None  # infer from override when present
    else:
        try:
            use_sigma_thresholds = str(sigma_env_raw).strip().lower() in {"1", "true", "yes"}
        except Exception:
            use_sigma_thresholds = False
    sigma_watch_by_stat: dict[str, float] = {
        # Conservative defaults: roughly "edge / typical sd".
        "pts": 0.55,
        "reb": 0.70,
        "ast": 0.70,
        "threes": 0.80,
        "pra": 0.55,
    }
    sigma_bet_by_stat: dict[str, float] = {
        "pts": 0.85,
        "reb": 1.05,
        "ast": 1.05,
        "threes": 1.15,
        "pra": 0.85,
    }
    sigma_watch_global = None
    sigma_bet_global = None

    # Optional: stricter market quality gating for klass.
    try:
        require_prices_for_signal = str(os.environ.get("LIVE_PLAYER_LENS_REQUIRE_PRICES_FOR_SIGNAL", "0")).strip().lower() in {"1", "true", "yes"}
    except Exception:
        require_prices_for_signal = False
    try:
        require_live_line_after_min = float(str(os.environ.get("LIVE_PLAYER_LENS_REQUIRE_LIVE_LINE_AFTER_MIN", "0")).strip())
    except Exception:
        require_live_line_after_min = 0.0
        require_live_line_after_min = float(
            max(0.0, min(float(getattr(LEAGUE, "regulation_team_minutes", 240.0)) / 5.0, require_live_line_after_min))
        )
    try:
        require_min_books = int(float(str(os.environ.get("LIVE_PLAYER_LENS_REQUIRE_MIN_BOOKS", "0")).strip()))
    except Exception:
        require_min_books = 0
    require_min_books = int(max(0, min(10, require_min_books)))
    # Player prop bettability gating (server-side): allow tuning override to control it.
    try:
        player_prop_bettability_gate = str(os.environ.get("LIVE_PLAYER_PROPS_BETTABLE_GATING", "0")).strip().lower() in {"1", "true", "yes"}
    except Exception:
        player_prop_bettability_gate = False
    try:
        player_prop_bettability_min_score = float(str(os.environ.get("LIVE_PROPS_BETTABLE_MIN_SCORE", "0.60")).strip())
    except Exception:
        player_prop_bettability_min_score = 0.60
    try:
        o = _live_load_lens_override()
        if isinstance(o, dict):
            mk = o.get("markets")
            if isinstance(mk, dict):
                pp = mk.get("player_prop")
                if isinstance(pp, dict):
                    w = _safe_float(pp.get("watch"))
                    b = _safe_float(pp.get("bet"))
                    if w is not None and w > 0:
                        player_prop_watch = float(w)
                    if b is not None and b > 0:
                        player_prop_bet = float(b)

                    # Optional sigma thresholds from override.
                    try:
                        wsg = _safe_float(pp.get("watch_sigma"))
                        bsg = _safe_float(pp.get("bet_sigma"))
                        if wsg is not None and wsg > 0:
                            sigma_watch_global = float(wsg)
                        if bsg is not None and bsg > 0:
                            sigma_bet_global = float(bsg)
                    except Exception:
                        pass
                    try:
                        st_cfg = pp.get("sigma_thresholds")
                        if isinstance(st_cfg, dict):
                            for k0, vv in st_cfg.items():
                                sk = _live_stat_key(k0)
                                if not isinstance(vv, dict):
                                    continue
                                ww = _safe_float(vv.get("watch"))
                                bb = _safe_float(vv.get("bet"))
                                if ww is not None and ww > 0:
                                    sigma_watch_by_stat[sk] = float(ww)
                                if bb is not None and bb > 0:
                                    sigma_bet_by_stat[sk] = float(bb)
                    except Exception:
                        pass

                    # If LIVE_PLAYER_LENS_SIGMA_THRESHOLDS isn't explicitly set,
                    # automatically enable sigma mode when override provides sigma thresholds.
                    if use_sigma_thresholds is None:
                        has_sigma = bool(
                            (sigma_watch_global is not None)
                            or (sigma_bet_global is not None)
                            or (isinstance(pp.get("sigma_thresholds"), dict) and len(pp.get("sigma_thresholds")) > 0)
                        )
                        use_sigma_thresholds = bool(has_sigma)

                    bett = pp.get("bettability")
                    if isinstance(bett, dict):
                        try:
                            g = bett.get("gating")
                            if g is not None:
                                player_prop_bettability_gate = bool(g)
                        except Exception:
                            pass
                        try:
                            ms = _safe_float(bett.get("min_score"))
                            if ms is not None and ms >= 0:
                                player_prop_bettability_min_score = float(ms)
                        except Exception:
                            pass
    except Exception:
        pass

    # Default: if env isn't set and override has no sigma thresholds, keep legacy behavior.
    if use_sigma_thresholds is None:
        use_sigma_thresholds = False

    # Lookups from processed artifacts (best-effort; may be missing)
    edges_idx: dict[tuple[str, str, str], float] = {}
    rec_lines_idx: dict[tuple[str, str, str], float] = {}
    preds_idx: dict[tuple[str, str], dict[str, Any]] = {}
    if d:
        try:
            edges_idx = _live_load_props_edges_index(d)
        except Exception:
            edges_idx = {}
        try:
            rec_lines_idx = _live_load_props_recommendations_line_index(d)
        except Exception:
            rec_lines_idx = {}
        try:
            preds_idx = _live_load_props_predictions_index(d)
        except Exception:
            preds_idx = {}

    best_bets_game_context: dict[str, Any] = {}
    if d:
        try:
            best_bets_game_context = _load_best_bets_game_context(d)
        except Exception:
            best_bets_game_context = {}

    # Best-effort mapping to game_id + teams + clock/period
    games_map: dict[str, dict[str, Any]] = {}
    if d:
        try:
            _src, sb_games = _live_build_scoreboard_games(d)
            for g in sb_games or []:
                eid = str(g.get("espn_event_id") or "").strip()
                if eid:
                    games_map[eid] = g
        except Exception:
            games_map = {}

    # Best-effort roster-based player_id lookup (fast, avoids per-row nba_api work).
    try:
        roster_pid_by_team_nk = _live_roster_pid_by_team_nk()
    except Exception:
        roster_pid_by_team_nk = {}

    def _num(x: Any) -> float | None:
        try:
            v = pd.to_numeric(x, errors="coerce")
            if pd.isna(v):
                return None
            return float(v)
        except Exception:
            return None

    def _pred_val(pred_row: dict[str, Any] | None, stat_key: str) -> float | None:
        if not pred_row:
            return None
        stat_key = _live_stat_key(stat_key)
        candidates = [
            f"mean_{stat_key}",
            f"pred_{stat_key}",
        ]
        for c in candidates:
            for k in [c, c.upper(), c.lower()]:
                if k in pred_row:
                    v = _num(pred_row.get(k))
                    if v is not None:
                        return v
        return None

    def _pred_exp_min(pred_row: dict[str, Any] | None) -> float | None:
        if not pred_row:
            return None
        for k in ["roll10_min", "roll5_min", "roll3_min", "lag1_min"]:
            for kk in [k, k.upper(), k.lower()]:
                if kk in pred_row:
                    v = _num(pred_row.get(kk))
                    if v is not None and v > 0:
                        return float(v)
        return None

    def _snapshot_prop_stat_key(market: Any) -> str | None:
        market_key = str(market or "").strip().lower()
        return {
            "player_points": "pts",
            "player_points_alternate": "pts",
            "player_rebounds": "reb",
            "player_rebounds_alternate": "reb",
            "player_assists": "ast",
            "player_assists_alternate": "ast",
            "player_threes": "threes",
            "player_threes_alternate": "threes",
            "player_points_rebounds_assists": "pra",
            "player_points_rebounds_assists_alternate": "pra",
            "player_points_assists": "pa",
            "player_points_assists_alternate": "pa",
            "player_points_rebounds": "pr",
            "player_points_rebounds_alternate": "pr",
            "player_rebounds_assists": "ra",
            "player_rebounds_assists_alternate": "ra",
            "player_steals": "stl",
            "player_steals_alternate": "stl",
            "player_blocks": "blk",
            "player_blocks_alternate": "blk",
            "player_turnovers": "tov",
            "player_turnovers_alternate": "tov",
        }.get(market_key)

    def _snapshot_prop_side(side: Any) -> str | None:
        side_key = str(side or "").strip().lower()
        if side_key in {"over", "o"}:
            return "over"
        if side_key in {"under", "u"}:
            return "under"
        return None

    def _snapshot_prop_line_token(line_val: Any) -> str | None:
        line_num = _safe_float(line_val)
        if line_num is None:
            return None
        return f"{float(line_num):.3f}"

    def _load_snapshot_props_for_game(date_str: str, home_tri: str, away_tri: str, player_team_by_nk: dict[str, str]) -> dict[str, dict[str, Any]]:
        out: dict[str, dict[str, Any]] = {"lines": {}, "prices": {}, "books": {}}
        if not date_str or not home_tri or not away_tri:
            return out
        try:
            snapshot_path = _live_find_processed_csv("oddsapi_player_props", date_str)
        except Exception:
            snapshot_path = None
        if not snapshot_path:
            return out
        try:
            df = pd.read_csv(snapshot_path)
        except Exception:
            return out
        if df is None or df.empty:
            return out

        cols = {str(c).strip().lower(): str(c) for c in df.columns}
        market_col = cols.get("market")
        name_col = cols.get("player_name")
        line_col = cols.get("point")
        side_col = cols.get("outcome_name")
        price_col = cols.get("price")
        book_col = cols.get("bookmaker")
        home_col = cols.get("home_team")
        away_col = cols.get("away_team")
        if not (market_col and name_col and line_col and side_col and price_col and book_col and home_col and away_col):
            return out

        points_by_key: dict[tuple[str, str, str], list[float]] = {}
        prices_by_line_side: dict[tuple[str, str, str, str, str], list[float]] = {}
        book_counts_by_line_side: dict[tuple[str, str, str, str, str], dict[str, int]] = {}
        home_tri = _canonical_team_tri(home_tri)
        away_tri = _canonical_team_tri(away_tri)

        for _, row in df.iterrows():
            try:
                row_home = _canonical_team_tri(_get_tricode(str(row.get(home_col) or "")))
                row_away = _canonical_team_tri(_get_tricode(str(row.get(away_col) or "")))
                if {row_home, row_away} != {home_tri, away_tri}:
                    continue
                nk0 = _norm_player_name(row.get(name_col))
                stat_key = _snapshot_prop_stat_key(row.get(market_col))
                side_key = _snapshot_prop_side(row.get(side_col))
                line_num = _safe_float(row.get(line_col))
                price_num = _safe_float(row.get(price_col))
                if not nk0 or not stat_key or not side_key or line_num is None or price_num is None:
                    continue
                team_tri = _canonical_team_tri(player_team_by_nk.get(nk0))
                if not team_tri:
                    home_match = (home_tri, nk0) in roster_pid_by_team_nk if isinstance(roster_pid_by_team_nk, dict) else False
                    away_match = (away_tri, nk0) in roster_pid_by_team_nk if isinstance(roster_pid_by_team_nk, dict) else False
                    if home_match and not away_match:
                        team_tri = home_tri
                    elif away_match and not home_match:
                        team_tri = away_tri
                if team_tri not in {home_tri, away_tri}:
                    continue
                player_key = (team_tri, nk0, stat_key)
                line_token = _snapshot_prop_line_token(line_num)
                if not line_token:
                    continue
                points_by_key.setdefault(player_key, []).append(float(line_num))
                price_key = (team_tri, nk0, stat_key, line_token, side_key)
                prices_by_line_side.setdefault(price_key, []).append(float(price_num))
                book_key = _canonical_bookmaker_key(row.get(book_col)) or None
                if book_key:
                    book_counts_by_line_side.setdefault(price_key, {})[book_key] = int(book_counts_by_line_side.setdefault(price_key, {}).get(book_key, 0)) + 1
            except Exception:
                continue

        for (team_tri, nk0, stat_key), points in points_by_key.items():
            try:
                if not points:
                    continue
                consensus_line = float(np.median(np.asarray(points, dtype=float)))
                line_token = _snapshot_prop_line_token(consensus_line)
                if not line_token:
                    continue
                base_key = f"{team_tri}|{nk0}|{stat_key}"
                out["lines"][base_key] = consensus_line
                price_entry: dict[str, Any] = {}
                book_entry: dict[str, Any] = {}
                for side_key in ("over", "under"):
                    price_key = (team_tri, nk0, stat_key, line_token, side_key)
                    prices = prices_by_line_side.get(price_key) or []
                    if prices:
                        price_entry[side_key] = float(np.median(np.asarray(prices, dtype=float)))
                    book_counts = book_counts_by_line_side.get(price_key) or {}
                    if book_counts:
                        best_book = min(book_counts.items(), key=lambda item: (-int(item[1]), str(item[0])))[0]
                        book_entry[side_key] = best_book
                if price_entry:
                    out["prices"][f"{base_key}|{line_token}"] = price_entry
                if book_entry:
                    out["books"][f"{base_key}|{line_token}"] = book_entry
            except Exception:
                continue
        return out

